You have access to the following relational tables, with schemas below.

CREATE TABLE classroom (building TEXT, room_number TEXT, capacity DECIMAL(4,0));

CREATE TABLE department (dept_name TEXT, building TEXT, budget DECIMAL(12,2));

CREATE TABLE course (course_id TEXT, title TEXT, dept_name TEXT, credits DECIMAL(2,0));

CREATE TABLE instructor (ID TEXT, name TEXT NOT NULL, dept_name TEXT, salary DECIMAL(8,2));

CREATE TABLE section (course_id TEXT, sec_id TEXT, semester TEXT, "year" DECIMAL(4,0), building TEXT, room_number TEXT, time_slot_id TEXT);

CREATE TABLE teaches (ID TEXT, course_id TEXT, sec_id TEXT, semester TEXT, "year" DECIMAL(4,0));

CREATE TABLE student (ID TEXT, name TEXT NOT NULL, dept_name TEXT, tot_cred DECIMAL(3,0));

CREATE TABLE takes (ID TEXT, course_id TEXT, sec_id TEXT, semester TEXT, "year" DECIMAL(4,0), grade TEXT);

CREATE TABLE advisor (s_ID TEXT, i_ID TEXT);

CREATE TABLE time_slot (time_slot_id TEXT, "day" TEXT, start_hr DECIMAL(2,0), start_min DECIMAL(2,0), end_hr DECIMAL(2,0), end_min DECIMAL(2,0));

CREATE TABLE prereq (course_id TEXT, prereq_id TEXT);

Write a SQL query to answer the following question:

What are the names of Art instructors who have taught a course, and the corresponding course id?

