You have access to the following relational tables, with schemas below.

CREATE TABLE city (ID INTEGER NOT NULL, Name TEXT NOT NULL DEFAULT '', CountryCode TEXT NOT NULL DEFAULT '', District TEXT NOT NULL DEFAULT '', Population INTEGER NOT NULL DEFAULT 0);

CREATE TABLE country (Code TEXT NOT NULL DEFAULT '', Name TEXT NOT NULL DEFAULT '', Continent TEXT NOT NULL DEFAULT 'Asia', Region TEXT NOT NULL DEFAULT '', SurfaceArea DOUBLE NOT NULL DEFAULT 0.0, IndepYear INTEGER, Population INTEGER NOT NULL DEFAULT 0, LifeExpectancy FLOAT, GNP FLOAT, GNPOld FLOAT, LocalName TEXT NOT NULL DEFAULT '', GovernmentForm TEXT NOT NULL DEFAULT '', HeadOfState TEXT, Capital INTEGER, Code2 TEXT NOT NULL DEFAULT '');

CREATE TABLE countrylanguage (CountryCode TEXT NOT NULL DEFAULT '', "Language" TEXT NOT NULL DEFAULT '', IsOfficial TEXT NOT NULL DEFAULT 'F', Percentage FLOAT NOT NULL DEFAULT 0.0);

Write a SQL query to answer the following question:

What are the names of countries that speak more than 2 languages, as well as how many languages they speak?

